const crypto = require('node:crypto');
const { promisify } = require('node:util');
const express = require('express');
const session = require('express-session');

const scrypt = promisify(crypto.scrypt);
const isProd = process.env.NODE_ENV === 'production';

// ---------------------------------------------------------------------------
// Password hashing (scrypt, built into Node — no native dependencies)
// ---------------------------------------------------------------------------

// OWASP-recommended scrypt parameters. maxmem must exceed 128 * N * r bytes.
const SCRYPT = { N: 2 ** 15, r: 8, p: 3, maxmem: 64 * 1024 * 1024 };
const KEY_LEN = 64;
const MAX_PASSWORD_LEN = 1024;

async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password, salt, KEY_LEN, SCRYPT);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [saltHex, keyHex] = stored.split(':');
  const expected = Buffer.from(keyHex, 'hex');
  const actual = await scrypt(password, Buffer.from(saltHex, 'hex'), expected.length, SCRYPT);
  return crypto.timingSafeEqual(actual, expected);
}

// ---------------------------------------------------------------------------
// Failed-attempt rate limiting (fixed window, in memory)
// ---------------------------------------------------------------------------

class AttemptLimiter {
  constructor({ max, windowMs }) {
    this.max = max;
    this.windowMs = windowMs;
    this.entries = new Map(); // key -> { count, resetAt }
    setInterval(() => this.sweep(), windowMs).unref();
  }

  // Counts an attempt. Returns 0 if allowed, otherwise seconds until unblocked.
  // Attempts are counted *before* the password check so that a burst of
  // concurrent requests can't all slip through ahead of the first failure.
  consume(key) {
    const now = Date.now();
    let entry = this.entries.get(key);
    if (!entry || entry.resetAt <= now) {
      entry = { count: 0, resetAt: now + this.windowMs };
      this.entries.set(key, entry);
    }
    if (entry.count >= this.max) return Math.ceil((entry.resetAt - now) / 1000);
    entry.count += 1;
    return 0;
  }

  // Gives back an attempt that turned out to be a successful login.
  refund(key) {
    const entry = this.entries.get(key);
    if (entry && entry.count > 0) entry.count -= 1;
  }

  reset(key) {
    this.entries.delete(key);
  }

  sweep() {
    const now = Date.now();
    for (const [key, entry] of this.entries) {
      if (entry.resetAt <= now) this.entries.delete(key);
    }
  }
}

const WINDOW_MS = 15 * 60 * 1000;
// Per-account limit stops targeted guessing; per-IP limit stops one client
// spraying passwords across many accounts.
const accountLimiter = new AttemptLimiter({ max: 5, windowMs: WINDOW_MS });
const ipLimiter = new AttemptLimiter({ max: 20, windowMs: WINDOW_MS });

// ---------------------------------------------------------------------------
// Users (in-memory stand-in for a database)
// ---------------------------------------------------------------------------

const users = new Map(); // username -> { id, username, passwordHash }

// Verified against when the username doesn't exist, so that unknown users take
// as long to reject as wrong passwords (no user enumeration via timing).
const dummyHash = hashPassword(crypto.randomBytes(32).toString('hex'));

function parseCredentials(body) {
  const { username, password } = body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  const name = username.trim().toLowerCase();
  if (!name || name.length > 64) return null;
  if (!password || password.length > MAX_PASSWORD_LEN) return null;
  return { username: name, password };
}

// ---------------------------------------------------------------------------
// App
// ---------------------------------------------------------------------------

const sessionSecret = process.env.SESSION_SECRET;
if (!sessionSecret && isProd) {
  throw new Error('SESSION_SECRET must be set in production');
}

const app = express();

// Behind a reverse proxy, set this so req.ip is the real client address and
// secure cookies work. Leave unset when clients connect directly.
if (process.env.TRUST_PROXY) app.set('trust proxy', Number(process.env.TRUST_PROXY));

app.use(express.json({ limit: '10kb' }));
app.use(
  session({
    name: 'sid',
    secret: sessionSecret || crypto.randomBytes(32).toString('hex'),
    resave: false,
    saveUninitialized: false, // no cookie until the user actually logs in
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: isProd,
      maxAge: 24 * 60 * 60 * 1000,
    },
    // Default MemoryStore is for development only; pass `store` (Redis, SQL, ...) in production.
  })
);

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated' });
  next();
}

app.post('/register', async (req, res) => {
  const creds = parseCredentials(req.body);
  if (!creds) return res.status(400).json({ error: 'Invalid username or password' });
  if (creds.password.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters' });
  }
  if (users.has(creds.username)) return res.status(409).json({ error: 'Username taken' });

  const user = {
    id: crypto.randomUUID(),
    username: creds.username,
    passwordHash: await hashPassword(creds.password),
  };
  users.set(user.username, user);
  res.status(201).json({ id: user.id, username: user.username });
});

app.post('/login', async (req, res) => {
  const creds = parseCredentials(req.body);
  if (!creds) return res.status(400).json({ error: 'Invalid username or password' });

  const retryAfter = ipLimiter.consume(req.ip) || accountLimiter.consume(creds.username);
  if (retryAfter) {
    res.set('Retry-After', String(retryAfter));
    return res.status(429).json({ error: 'Too many failed attempts. Try again later.' });
  }

  const user = users.get(creds.username);
  const ok = await verifyPassword(creds.password, user ? user.passwordHash : await dummyHash);
  if (!user || !ok) {
    // Same response for unknown user and wrong password.
    return res.status(401).json({ error: 'Invalid username or password' });
  }

  ipLimiter.refund(req.ip);
  accountLimiter.reset(creds.username);

  // New session ID on privilege change, to prevent session fixation.
  await new Promise((resolve, reject) =>
    req.session.regenerate((err) => (err ? reject(err) : resolve()))
  );
  req.session.userId = user.id;
  req.session.username = user.username;
  res.json({ id: user.id, username: user.username });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.status(204).end();
  });
});

app.get('/me', requireAuth, (req, res) => {
  res.json({ id: req.session.userId, username: req.session.username });
});

app.use((err, req, res, next) => {
  if (err.type === 'entity.parse.failed' || err.type === 'entity.too.large') {
    return res.status(400).json({ error: 'Invalid request body' });
  }
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

const port = Number(process.env.PORT) || 3000;
app.listen(port, () => console.log(`Listening on http://localhost:${port}`));

